//! Synthetic 2CBH fixtures for the tests, built from the layout in
//! `docs/format-spec-2cbh.md` rather than from any real database.
//!
//! The local ChessBase sets are copyrighted and are **not** in this repository,
//! and neither is anything derived from their bytes. Every byte a test here
//! reads is therefore generated by the functions below from the *verified
//! layout* — the frame arithmetic, the little-endian fields, the
//! `88 77 66 55 44 33 22 11` magic and the `ff ff` terminator are the format's,
//! not a copy of anyone's game, name or commentary. A test that needs a real
//! set is gated on `CBVAULT_TEST_2CBH` and says loudly that it did not run.

use std::path::{Path, PathBuf};

use super::bytes::{CONTENT_OFFSET, FILE_HEADER_SIZE, FIXED_OVERHEAD, RECORD_MAGIC, RECORD_SIZE};
use super::record::checksum;

/// A 12-byte `.2cbg`/`.2cba` file header for a file of `size` bytes, with the
/// first record at [`FILE_HEADER_SIZE`].
pub fn file_header(size: u64) -> [u8; FILE_HEADER_SIZE] {
    let mut h = [0u8; FILE_HEADER_SIZE];
    h[0..8].copy_from_slice(&size.to_le_bytes());
    h[8..10].copy_from_slice(&(FILE_HEADER_SIZE as u16).to_le_bytes());
    h
}

/// A whole record: magic, A/B lengths, big-endian checksum, two-byte tag,
/// A content bytes, B spare bytes, and an eight-byte length trailer.
/// Generated entirely from synthetic content, without ChessBase source data.
///
/// `a` is taken from the content length, so a caller passes the bytes it wants
/// and the frame is built around them.
pub fn record(b: u32, content: &[u8]) -> Vec<u8> {
    record_with(content.len() as u32, b, content)
}

/// The same as [`record`], with `a` stated explicitly — for a test that
/// corrupts a length field and needs the stated value not to be recomputed.
pub fn record_with(a: u32, b: u32, content: &[u8]) -> Vec<u8> {
    assert_eq!(a as usize, content.len());
    assert_eq!(CONTENT_OFFSET + a as usize + b as usize + 8, FIXED_OVERHEAD + a as usize + b as usize);
    let total = FIXED_OVERHEAD + a as usize + b as usize;
    let mut r = Vec::with_capacity(total);
    r.extend_from_slice(&RECORD_MAGIC);
    r.extend_from_slice(&a.to_le_bytes());
    r.extend_from_slice(&b.to_le_bytes());
    r.extend_from_slice(&checksum(content).to_be_bytes());
    r.extend_from_slice(&1u16.to_le_bytes()); // standard-chess game tag
    r.extend_from_slice(content);
    r.resize(total, 0);
    let n = r.len();
    r[n - 8..].copy_from_slice(&(n as u64).to_le_bytes());
    r
}

/// A `.2cbg`/`.2cba` file of the given records, with the header's size field
/// filled in to match.
pub fn segment(records: &[Vec<u8>]) -> Vec<u8> {
    let body: usize = records.iter().map(|r| r.len()).sum();
    let size = (FILE_HEADER_SIZE + body) as u64;
    let mut out = file_header(size).to_vec();
    for r in records {
        out.extend_from_slice(r);
    }
    out
}

/// A 192-byte v2 header with raw entity IDs. Player names live in .2lid,
/// not at 0x68/0x78 (those are rating-related metadata).
pub fn header_record(flags: u8, moves: u64, annotations: u64, players: (i64, i64)) -> [u8; RECORD_SIZE] {
    let mut b = [0u8; RECORD_SIZE];
    b[0] = flags;
    b[0x01] = 0x00;
    b[0x02] = 0x01;
    b[0x03] = 0x01;
    b[0x08..0x10].copy_from_slice(&moves.to_le_bytes());
    b[0x10..0x18].copy_from_slice(&annotations.to_le_bytes());
    b[0x40..0x50].fill(0xff);
    b[0x18..0x20].copy_from_slice(&players.0.to_le_bytes());
    b[0x20..0x28].copy_from_slice(&players.1.to_le_bytes());
    b[0xb8..0xbc].copy_from_slice(&1u32.to_le_bytes());
    b
}

/// A whole `.2cbh` file: its own header record (stating the count and the
/// record size) followed by `games`.
///
/// The count field is the **total** number of 192-byte records, the file's own
/// included — verified against every local set (a 21,143,232-byte file states
/// 110,121 = size/192) — so it is one more than the number of games.
pub fn headers(games: &[[u8; RECORD_SIZE]], generation: u8) -> Vec<u8> {
    let mut out = vec![0u8; RECORD_SIZE];
    out[0x08] = generation;
    out[0x0a..0x0c].copy_from_slice(&(RECORD_SIZE as u16).to_le_bytes());
    out[0x10..0x14].copy_from_slice(&((games.len() + 1) as u32).to_le_bytes());
    for g in games {
        out.extend_from_slice(g);
    }
    out
}

/// A fully synthetic .2lid with a fixed-size container for each of six
/// entity kinds. The 0th ID is intentionally empty; ordinary player IDs
/// contain deterministic dummy names that cannot identify real people.
pub fn entity_registry(last_id: u32) -> Vec<u8> {
    const SIZE: [usize; 6] = [128, 128, 64, 64, 64, 128];
    const TYPES: usize = 6;
    let head = 8 + 20 * TYPES;
    let block: usize = SIZE.iter().sum();
    let count = last_id as usize + 1;
    let mut bytes = vec![0u8; head + count * block];
    bytes[..4].copy_from_slice(&(head as i32).to_be_bytes());
    bytes[4..8].copy_from_slice(&(TYPES as i32).to_be_bytes());
    for (kind, sz) in SIZE.into_iter().enumerate() {
        let o = 8 + kind * 20;
        bytes[o..o + 4].copy_from_slice(&(sz as i32).to_be_bytes());
        bytes[o + 4..o + 12].copy_from_slice(&(count as i64).to_be_bytes());
        bytes[o + 12..o + 20].copy_from_slice(&(-1i64).to_be_bytes());
    }
    // Every ID after 0 is an artificial person named Test<ID>, Example.
    for id in 1..count {
        let start = head + id * block;
        let last = format!("Test{id}");
        let first = b"Example";
        let mut payload = Vec::new();
        payload.extend_from_slice(&(last.len() as i32).to_le_bytes());
        payload.extend_from_slice(last.as_bytes());
        payload.extend_from_slice(&(first.len() as i32).to_le_bytes());
        payload.extend_from_slice(first);
        bytes[start..start + 4].copy_from_slice(&(payload.len() as i32).to_le_bytes());
        bytes[start + 4..start + 4 + payload.len()].copy_from_slice(&payload);
    }
    bytes
}

/// One synthetic game: its flags, per-game key, and two entity IDs.
#[derive(Clone, Copy)]
pub struct Game {
    /// Record flags; bit 0x80 marks a deleted record.
    pub kind: u8,
    /// The value stored at `0x98`, distinct per game as in the real sets.
    pub key: u64,
    /// The two player entity IDs in the .2lid registry.
    pub players: (i64, i64),
}

impl Game {
    /// A game with the given key and two player entity IDs.
    pub fn new(key: u64, white: i64, black: i64) -> Game {
        Game { kind: 1, key, players: (white, black) }
    }
}

/// Writes a synthetic 2CBH set of `games` into a uniquely named directory
/// under the temp dir and returns its base path, laid out as the real sets
/// are: `.2cbh`, and `.2cbg`/`.2cba` each a 12-byte header then records.
///
/// With `annotations` false no `.2cba` is written, which is the one member a
/// caller can legitimately find missing.
pub fn write_set(tag: &str, games: &[Game], annotations: bool) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("cbvault-twocbh-{}-{tag}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("the fixture directory");
    let stem = dir.join("fixture");

    let mut heads: Vec<[u8; RECORD_SIZE]> = Vec::new();
    let mut moves: Vec<Vec<u8>> = Vec::new();
    let mut notes: Vec<Vec<u8>> = Vec::new();
    let mut next_move = FILE_HEADER_SIZE as u64;
    let mut next_note = FILE_HEADER_SIZE as u64;
    for g in games {
        // FFFC starts a legal-format empty tree, FFFF ends its main line.
        let m = record(102, &[0xfc, 0xff, 0xff, 0xff]);
        let mo = next_move;
        next_move += m.len() as u64;
        let ao = if annotations {
            // Empty v2 annotation record: position sentinel only, with
            // the mandatory 0x2000 2CBA frame tag.
            let mut a = record(198, &0x7fff_ffffi32.to_le_bytes());
            a[0x18..0x1a].copy_from_slice(&0x2000u16.to_le_bytes());
            let at = next_note;
            next_note += a.len() as u64;
            notes.push(a);
            at
        } else {
            0
        };
        let mut h = header_record(g.kind, mo, ao, g.players);
        h[0x98..0xa0].copy_from_slice(&g.key.to_le_bytes());
        heads.push(h);
        moves.push(m);
    }
    std::fs::write(format!("{}.2cbh", stem.display()), headers(&heads, 0x22)).expect("write .2cbh");
    std::fs::write(format!("{}.2cbg", stem.display()), segment(&moves)).expect("write .2cbg");
    let max_id = games.iter().flat_map(|g| [g.players.0, g.players.1]).max().unwrap_or(0).max(0) as u32;
    std::fs::write(format!("{}.2lid", stem.display()), entity_registry(max_id)).expect("write .2lid");
    if annotations {
        std::fs::write(format!("{}.2cba", stem.display()), segment(&notes)).expect("write .2cba");
    }
    stem
}

/// Removes a set written by [`write_set`].
pub fn remove_set(stem: &Path) {
    if let Some(dir) = stem.parent() {
        let _ = std::fs::remove_dir_all(dir);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_written_set_has_the_count_its_header_states() {
        let games = [Game::new(1, 1, 2), Game::new(2, 3, 4)];
        let stem = write_set("count", &games, true);
        let bytes = std::fs::read(format!("{}.2cbh", stem.display())).unwrap();
        assert_eq!(bytes.len() / RECORD_SIZE, 3, "the file's own record plus two games");
        assert_eq!(u32::from_le_bytes(bytes[0x10..0x14].try_into().unwrap()), 3);
        remove_set(&stem);
    }
}
